def get_classes():
    return ["7", "8", "9"]

def get_subjects(class_id: str):
    return list(CBSE_SYLLABUS.get(class_id, {}).keys())

def get_chapters(class_id: str, subject: str):
    subject_data = CBSE_SYLLABUS.get(class_id, {}).get(subject, {})
    return subject_data.get("chapters", [])

def get_subject_meta(class_id: str, subject: str):
    data = CBSE_SYLLABUS.get(class_id, {}).get(subject, {})
    return {"icon": data.get("icon", "book"), "color": data.get("color", "#06b6d4")}
